import org.apache.nifi.processor.io.StreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.time.*
import java.time.format.DateTimeFormatter

flowFile = session.get()
if (!flowFile) return

// output list must be outside callback to avoid MissingPropertyException
def outputList = []

try {
    flowFile = session.write(flowFile, { inputStream, outputStream ->

        def json = new JsonSlurper().parse(inputStream)

        // Raw timestamp from ADSB
        def ts = json.timestamp ? (json.timestamp as long) : null

		def ts_String = json.timestamp ? (json.timestamp.toString()) : null

        // Convert to Instant
        Instant utcInstant = ts ? Instant.ofEpochMilli(ts) : null

        // time → ISO UTC
        def timeUtcIso = utcInstant ? utcInstant.toString() : null

        // time_ist → yyyy-MM-dd HH:mm:ss
        def timeIstFormatted = null
        if (utcInstant) {
            ZoneId istZone = ZoneId.of("Asia/Kolkata")
            LocalDateTime istTime = LocalDateTime.ofInstant(utcInstant, istZone)
            timeIstFormatted = istTime.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
        }

        ZoneId ist = ZoneId.of("Asia/Kolkata")
		def createdDate = ZonedDateTime.now(ist).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))

        json.each { key, value ->

            if (key == "timestamp" || key == "update_age") return

            try {
                List data = (value instanceof List) ? value : []

				// HEX → DECIMAL conversion
                long modeSId = Long.parseLong(key, 16)
				long flightId = modeSId                  // store this separately as flight_id

                def safeInt = { idx ->
                    try {
                        return (data[idx] != null && data[idx].toString().trim() != "")
                                ? (data[idx] as Integer)
                                : null
                    } catch (Exception e) { return null }
                }

                def safeDouble = { idx ->
                    try {
                        return (data[idx] != null && data[idx].toString().trim() != "")
                                ? (data[idx] as Double)
                                : null
                    } catch (Exception e) { return null }
                }

                def row = [
                    id            : null,
                    live_plot_id  : null,
                    track_id      : null,

                    time          : ts,          // from ts long
                    time_ist      : timeIstFormatted,    // IST converted

                    latitude      : safeDouble(4),
                    longitude     : safeDouble(5),
                    speed         : safeInt(7),
                    heading       : safeInt(8),
                    flight_level  : safeInt(6),
                    roc           : safeInt(9),
                    ssr           : data[3]?.toString(),
                    mode_s_id     : modeSId,
                    flight_status : null,
                    is_vehicle    : false,
                    ac_type       : null,
                    callsign      : data[0]?.toString()?.trim(),
                    registration  : null,
                    flight_id     : flightId,
                    ad            : null,
                    flightnumber  : data[0]?.toString()?.trim(),
                    att           : null,
                    ett           : null,
                    stt           : null,
                    ott           : null,
                    runway        : null,
                    distance      : null,

                    created_date  : createdDate
                ]

                outputList << row

            } catch (Exception ex) {
                log.error("Failed to process ADSB record for key=${key}", ex)
            }
        }

        outputStream.write(
            JsonOutput.prettyPrint(JsonOutput.toJson(outputList))
                      .getBytes("UTF-8")
        )

    } as StreamCallback)

    flowFile = session.putAttribute(flowFile, "record.count", outputList.size().toString())
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error parsing ADSB JSON", e)
    session.transfer(flowFile, REL_FAILURE)
}

