                                ? (data[idx] as Double)
                                : null
                    } catch (Exception e) { return null }
                }

                def row = [
                    id            : null,
                    live_plot_id  : null,
                    track_id      : null,

                    time          : ts_String,          // from ts_String
                    time_ist      : timeIstFormatted,    // IST converted

                    latitude      : safeDouble(4),
                    longitude     : safeDouble(5),
                    speed         : safeInt(7),
                    heading       : safeInt(8),
                    flight_level  : safeInt(6),
                    roc           : safeInt(9),
                    ssr           : data[3]?.toString(),
                    mode_s_id     : modeSId,
                    flight_status : null,
                    is_vehicle    : false,
                    ac_type       : null,
                    callsign      : data[0]?.toString()?.trim(),
                    registration  : null,
                    flight_id     : flightId,
                    ad            : null,
                    flightnumber  : data[0]?.toString()?.trim(),
                    att           : null,
                    ett           : null,
                    stt           : null,
                    ott           : null,
                    runway        : null,
                    distance      : null,

                    created_date  : createdDate
                ]

                outputList << row

            } catch (Exception ex) {
                log.error("Failed to process ADSB record for key=${key}", ex)
            }
        }

        outputStream.write(
            JsonOutput.prettyPrint(JsonOutput.toJson(outputList))
                      .getBytes("UTF-8")
        )

    } as StreamCallback)

    flowFile = session.putAttribute(flowFile, "record.count", outputList.size().toString())
    session.transfer(flowFile, REL_SUCCESS)

} catch (Exception e) {
    log.error("Error parsing ADSB JSON", e)
    session.transfer(flowFile, REL_FAILURE)
}
